{"implementation": "def solve(case):
    payload = case['payload']
    if 'text' not in payload or not isinstance(payload['text'], str):
        raise ValueError("Missing or invalid 'text'")
    if 'passes' not in payload or not isinstance(payload['passes'], list):
        raise ValueError("Missing or invalid 'passes'")
    for p in payload['passes']:
        if not isinstance(p, dict) or 'name' not in p or 'old' not in p or 'new' not in p:
            raise ValueError("Invalid pass entry")
        if not all(isinstance(v, str) for v in (p['name'], p['old'], p['new'])):
            raise ValueError("Pass fields must be strings")
    if 'max_rounds' not in payload or not isinstance(payload['max_rounds'], int) or payload['max_rounds'] < 0:
        raise ValueError("Missing or invalid 'max_rounds'")
    text = payload['text']
    passes = payload['passes']
    max_rounds = payload['max_rounds']
    current = text
    trace = []
    rounds = 0
    changed = True
    while rounds < max_rounds and changed:
        changed = False
        for p in passes:
            old = p['old']
            new = p['new']
            idx = current.find(old)
            if idx != -1:
                current = current[:idx] + new + current[idx+len(old):]
                trace.append(p['name'])
                changed = True
        rounds += 1
    fixed_point = not changed
    return {"artifact": current, "trace": trace, "fixed_point": fixed_point}
"}
